# Sum amounts per region with records.
type Entry = { kind: Str, weight: Int }

fn read_at(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn fold_in(m: Map[Str, Int], k: Str, v: Int) -> Map[Str, Int] =
  map_put(m, k, read_at(m, k) + v)

fn by_kind(xs: List[Entry]) -> Map[Str, Int] =
  fold(xs, map_new(), fn(acc, s) => fold_in(acc, s.kind, s.weight))

