fn adj_of(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn holds(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn roam(a: List[List[Int]], q: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(v) => if holds(vis, v) then roam(a, q, i + 1, vis) else roam(a, q ++ filter(adj_of(a, v), fn(u) => !holds(push(vis, v), u)), i + 1, push(vis, v)) }
fn order(a: List[List[Int]], s: Int) -> List[Int] = roam(a, [s], 0, [])
test mixed_order = order([[1, 4], [0, 2], [1, 3], [2, 4], [3, 0]], 0) == [0, 1, 4, 2, 3]

fn toggle(s: Str) -> Str =
  fold(chars(s), "", fn(out, c) =>
    if c == to_upper(c) && c != to_lower(c) then out ++ to_lower(c) else out ++ to_upper(c))

