fn at(xs: List[Int], i: Int) -> Int = match get(xs, i) { Some(v) => v, None => -1 }
fn index_of_val(xs: List[Int], x: Int, i: Int) -> Int =
  if i >= len(xs) then -1 else if at(xs, i) == x then i else index_of_val(xs, x, i + 1)
