# Record counters with tick, reset and a sum.
type Gauge = { tag: Str, level: Int }

fn advance(c: Gauge) -> Gauge =
  Gauge { tag: c.tag, level: c.level + 1 }

fn zero(c: Gauge) -> Gauge =
  Gauge { tag: c.tag, level: 0 }

fn combined(cs: List[Gauge]) -> Int =
  fold(cs, 0, fn(a, c) => a + c.level)

