type Grid = { rows: Int, cols: Int, cells: List[Int] }
fn cell(g: Grid, r: Int, c: Int) -> Int = list_at(g.cells, r * g.cols + c)
fn rot(g: Grid) -> Grid = Grid { rows: g.cols, cols: g.rows, cells: rot_cells(g, 0) }
fn rot_cells(g: Grid, c: Int) -> List[Int] = if c >= g.cols then [] else map(range(0, g.rows), fn(r) => cell(g, g.rows - 1 - r, c)) ++ rot_cells(g, c + 1)
test rotate_once = let m = rot(Grid { rows: 2, cols: 3, cells: [1, 2, 3, 4, 5, 6] }) in m.cells == [4, 1, 5, 2, 6, 3]

fn byte_or(b: Bytes, i: Int, d: Int) -> Int = match bytes_get(b, i) { Some(v) => v, None => d }
fn changes_at(b: Bytes, i: Int) -> Int = if i >= bytes_len(b) then 0 else (if byte_or(b, i, 0) == byte_or(b, i - 1, 0) then 0 else 1) + changes_at(b, i + 1)
