fn links(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn member(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn dive(a: List[List[Int]], v: Int, vis: List[Int]) -> List[Int] = if member(vis, v) then vis else fan(a, links(a, v), 0, push(vis, v))
fn fan(a: List[List[Int]], row: List[Int], i: Int, vis: List[Int]) -> List[Int] = if i >= len(row) then vis else match get(row, i) { None => vis, Some(u) => fan(a, row, i + 1, dive(a, u, vis)) }
fn order_of(a: List[List[Int]], v: Int) -> List[Int] = dive(a, v, [])
