fn shared_start(a: Str, b: Str) -> Str = walk(a, b, 0)

fn walk(a: Str, b: Str, i: Int) -> Str =
  if i >= len(a) || i >= len(b) then slice(a, 0, i)
  else if slice(a, i, i + 1) == slice(b, i, i + 1) then walk(a, b, i + 1)
  else slice(a, 0, i)

