type Creds = { user: Int, pass: Int }
type LoginErr = BadUser | BadPass | Locked
fn login(c: Creds, locked: Bool) -> Result[Int, LoginErr] =
  if locked then Err(Locked)
  else if c.user != 1 then Err(BadUser)
  else if c.pass != 1234 then Err(BadPass)
  else Ok(c.user)
