fn nb(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn has(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn dfs(a: List[List[Int]], v: Int, vis: List[Int]) -> List[Int] = if has(vis, v) then vis else scan(a, nb(a, v), 0, push(vis, v))
fn scan(a: List[List[Int]], row: List[Int], i: Int, vis: List[Int]) -> List[Int] = if i >= len(row) then vis else match get(row, i) { None => vis, Some(u) => scan(a, row, i + 1, dfs(a, u, vis)) }
fn star_order(a: List[List[Int]], v: Int) -> List[Int] = dfs(a, v, [])
