type Tree[T] = Leaf | Node(Tree[T], T, Tree[T])
fn digits(t: Tree[Int]) -> Tree[Str] = match t { Leaf => Leaf, Node(l, x, r) => Node(digits(l), from_int(x), digits(r)) }
