fn positionOf(xs: List[Int], target: Int) -> Option[Int] =
  let start: Option[Int] = None in
  fold(range(0, len(xs)), start, fn(acc: Option[Int], i: Int) =>
    match acc {
      Some(_) => acc,
      None => if list_at(xs, i) == target then Some(i) else None
