type Tok = Num(Int) | Plus | Times
fn t_apply(s: List[Int], t: Tok) -> List[Int] =
  match t {
    Num(n) => push(s, n),
    Plus => if len(s) < 2 then s else push(take_n(s, len(s) - 2), list_at(s, len(s) - 2) + list_at(s, len(s) - 1)),
    Times => if len(s) < 2 then s else push(take_n(s, len(s) - 2), list_at(s, len(s) - 2) * list_at(s, len(s) - 1))
  }
fn take_n(xs: List[Int], n: Int) -> List[Int] = fold(range(0, n), [], fn(a: List[Int], i: Int) => push(a, list_at(xs, i)))
fn eval(ts: List[Tok], s: List[Int]) -> List[Int] = fold(ts, s, fn(a: List[Int], t: Tok) => t_apply(a, t))
