fn lit(g: List[List[Bool]], r: Int, c: Int) -> Bool =
  if r < 0 then false
  else if r >= len(g) then false
  else match get(g, r) { None => false, Some(row) => if c < 0 then false else if c >= len(row) then false else match get(row, c) { None => false, Some(b) => b } }
fn around(r: Int, c: Int) -> List[Int] =
  (if r > 0 then [(r - 1) * 3 + c] else []) ++ (if r < 2 then [(r + 1) * 3 + c] else []) ++ (if c > 0 then [r * 3 + c - 1] else []) ++ (if c < 2 then [r * 3 + c + 1] else [])
fn holds(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn flow(g: List[List[Bool]], q: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(k) => if holds(vis, k) then flow(g, q, i + 1, vis) else flow(g, q ++ filter(around(k / 3, k % 3), fn(n) => lit(g, n / 3, n % 3) && !holds(push(vis, k), n)), i + 1, push(vis, k)) }
fn basin_from(g: List[List[Bool]], s: Int) -> Int = len(flow(g, [s], 0, []))
