fn nb(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn has(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn expand(a: List[List[Int]], fr: List[Int], vis: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(fr) then acc
  else match get(fr, i) { None => acc, Some(v) => expand(a, fr, vis, i + 1, acc ++ filter(nb(a, v), fn(u) => !has(vis, u))) }
fn jumps(a: List[List[Int]], fr: List[Int], vis: List[Int], goal: Int, d: Int) -> Int =
  if has(fr, goal) then d
  else if len(fr) == 0 then -1
  else after(a, fr, vis, goal, d, expand(a, fr, vis, 0, []))
