type Sides = { lower: List[Int], upper: List[Int] }

fn dropHead(xs: List[Int]) -> List[Int] =
  map(range(1, len(xs)), fn(i: Int) => list_at(xs, i))

fn cutAt(xs: List[Int], p: Int) -> Sides =
  let start = Sides { lower: [], upper: [] } in
  fold(xs, start, fn(acc: Sides, x: Int) =>
    if x < p then Sides { lower: push(acc.lower, x), upper: acc.upper }
    else Sides { lower: acc.lower, upper: push(acc.upper, x) })

fn sortIt(xs: List[Int]) -> List[Int] =
  if len(xs) <= 1 then xs
  else let p = list_at(xs, 0) in
       let rest = dropHead(xs) in
       let parts = cutAt(rest, p) in
       sortIt(parts.lower) ++ [p] ++ sortIt(parts.upper)

