fn heap(rs: List[Row], i: Int, acc: List[List[Int]]) -> List[List[Int]] =
  if i >= len(rs) then acc
  else match get(rs, i) { None => acc, Some(r) => heap(rs, i + 1, push(acc, row_list(r))) }
fn links(rs: List[Row], v: Int) -> List[Int] = match get(heap(rs, 0, []), v) { None => [], Some(xs) => xs }
fn has(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn sweep(rs: List[Row], q: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(v) => if has(vis, v) then sweep(rs, q, i + 1, vis) else sweep(rs, q ++ filter(links(rs, v), fn(u) => !has(push(vis, v), u)), i + 1, push(vis, v)) }
