fn none_list() -> List[Int] = []

fn list_slot(m: Map[Str, List[Int]], k: Str) -> List[Int] =
  match map_get(m, k) { Some(xs) => xs, None => none_list() }

fn insert(m: Map[Str, List[Int]], k: Str, n: Int) -> Map[Str, List[Int]] =
  map_put(m, k, push(list_slot(m, k), n))

