# A list of operations changes a counter map.
type Op = Add(Str) | Keep(Str) | Cut(Str)

fn lookup(m: Map[Str, Int], k: Str) -> Int =
  match map_get(m, k) { Some(n) => n, None => 0 }

fn step(m: Map[Str, Int], op: Op) -> Map[Str, Int] = match op {
  Add(k) => map_put(m, k, lookup(m, k) + 1),
  Keep(k) => map_put(m, k, lookup(m, k)),
  Cut(k) => map_del(m, k),
}

fn run(ops: List[Op], m: Map[Str, Int]) -> Map[Str, Int] =
  fold(ops, m, fn(acc, op) => step(acc, op))

test lookup_double = lookup(run([Add("a"), Add("a")], map_new()), "a") == 2
test run_cut = !map_has(run([Add("b"), Cut("b")], map_new()), "b")
test run_size = map_size(run([Add("c"), Add("d"), Keep("c")], map_new())) == 2

