type Board = { squares: List[Int] }
fn sq(b: Board, i: Int) -> Int = list_at(b.squares, i)
fn line3(a: Int, b: Int, c: Int) -> Bool = a != 0 && a == b && b == c
fn winner(b: Board) -> Int = if line3(sq(b, 0), sq(b, 1), sq(b, 2)) then sq(b, 0) else if line3(sq(b, 3), sq(b, 4), sq(b, 5)) then sq(b, 3) else if line3(sq(b, 6), sq(b, 7), sq(b, 8)) then sq(b, 6) else if line3(sq(b, 0), sq(b, 3), sq(b, 6)) then sq(b, 0) else if line3(sq(b, 1), sq(b, 4), sq(b, 7)) then sq(b, 1) else if line3(sq(b, 2), sq(b, 5), sq(b, 8)) then sq(b, 2) else if line3(sq(b, 0), sq(b, 4), sq(b, 8)) then sq(b, 0) else if line3(sq(b, 2), sq(b, 4), sq(b, 6)) then sq(b, 2) else 0
