fn p113_gp(r: Int, c: Int) -> Int = if r < 0 || c < 0 then 0 else if r == 0 && c == 0 then 1 else p113_gp(r - 1, c) + p113_gp(r, c - 1) + p113_gp(r - 1, c - 1)
