fn adj_of(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn holds(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn spread(a: List[List[Int]], fr: List[Int], vis: List[Int], i: Int, acc: List[Int]) -> List[Int] =
  if i >= len(fr) then acc
  else match get(fr, i) { None => acc, Some(v) => spread(a, fr, vis, i + 1, acc ++ filter(adj_of(a, v), fn(u) => !holds(vis, u))) }
fn band(a: List[List[Int]], fr: List[Int], vis: List[Int], k: Int) -> List[Int] =
  if k <= 0 then vis ++ fr else band(a, spread(a, fr, vis, 0, []), vis ++ fr, k - 1)
fn close(a: List[List[Int]], x: Int, y: Int, k: Int) -> Bool = holds(band(a, [x], [], k), y)
test two_hops = close([[1, 2], [0, 3], [0], [1]], 0, 3, 2) && !close([[1], [2], [3], []], 0, 3, 2)

type Date = { y: Int, m: Int, d: Int }
fn is_leap(y: Int) -> Bool = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
fn month_len(y: Int, m: Int) -> Int = match m { 2 => if is_leap(y) then 29 else 28, 4 => 30, 6 => 30, 9 => 30, 11 => 30, _ => 31 }
fn shift(d: Date, n: Int) -> Date = let total = d.y * 12 + (d.m - 1) + n in let y2 = total / 12 in let m2 = total % 12 + 1 in let d2 = if d.d > month_len(y2, m2) then month_len(y2, m2) else d.d in Date { y: y2, m: m2, d: d2 }
test back_one = let q = shift(Date { y: 2024, m: 3, d: 31 }, -1) in q.m == 2 && q.d == 29
test back_year = let q = shift(Date { y: 2024, m: 12, d: 31 }, -12) in q.y == 2023 && q.m == 12 && q.d == 31

