# A map from keys to small two-field tallies.
type Score = { ok: Int, bad: Int }

fn hit(m: Map[Str, Score], k: Str) -> Map[Str, Score] =
  match map_get(m, k) {
    Some(t) => map_put(m, k, Score { ok: t.ok + 1, bad: t.bad }),
    None => map_put(m, k, Score { ok: 1, bad: 0 }),
  }

fn fail(m: Map[Str, Score], k: Str) -> Map[Str, Score] =
  match map_get(m, k) {
    Some(t) => map_put(m, k, Score { ok: t.ok, bad: t.bad + 1 }),
    None => map_put(m, k, Score { ok: 0, bad: 1 }),
  }

fn oks(m: Map[Str, Score], k: Str) -> Int =
  match map_get(m, k) { Some(t) => t.ok, None => 0 }

test hit_hits = oks(hit(map_new(), "a"), "a") == 1
test fail_hits = oks(fail(map_new(), "b"), "b") == 0
test hit_size = map_size(fail(hit(map_new(), "c"), "c")) == 1

fn links(a: List[List[Int]], v: Int) -> List[Int] = match get(a, v) { Some(r) => r, None => [] }
fn known(xs: List[Int], x: Int) -> Bool = len(filter(xs, fn(y) => y == x)) > 0
fn crawl(a: List[List[Int]], q: List[Int], i: Int, vis: List[Int]) -> List[Int] =
  if i >= len(q) then vis
  else match get(q, i) { None => vis, Some(v) => if known(vis, v) then crawl(a, q, i + 1, vis) else crawl(a, q ++ filter(links(a, v), fn(u) => !known(push(vis, v), u)), i + 1, push(vis, v)) }
fn order(a: List[List[Int]], s: Int) -> List[Int] = crawl(a, [s], 0, [])
test ring_reverse = order([[3], [0], [1], [2]], 0) == [0, 3, 2, 1]

# Count integers by the bucket they fall into.
fn band(n: Int) -> Int = n / 3

fn read_int(m: Map[Int, Int], k: Int) -> Int =
