type Entry = { key: Str, value: Str }

fn parse_entry(s: Str) -> Option[Entry] =
  match index_of(s, "=") {
    None => None,
    Some(i) => Some(Entry { key: trim(slice(s, 0, i)), value: trim(slice(s, i + 1, len(s))) })
  }

fn query_map(query: Str) -> Map[Str, Str] =
  let start: Map[Str, Str] = map_new() in
  fold(split(query, "&"), start, fn(m, part) =>
    match parse_entry(part) {
      None => m,
      Some(e) => map_put(m, e.key, e.value)
    })

test query_map_ok = map_get(query_map("a=1&b=2"), "b") == Some("2")

type Strip = { lo: Int, hi: Int }
