  if k <= 0 then [] else if s.lo + k >= s.hi then [] else concat([s.lo + k], strip_step(Strip { lo: s.lo + k, hi: s.hi }, k))
test step_two = strip_step(Strip { lo: 0, hi: 6 }, 2) == [2, 4]

type Sheet = { rows: Int, cols: Int, cells: List[Int] }
fn column(s: Sheet, c: Int) -> List[Int] = map(range(0, s.rows), fn(r) => list_at(s.cells, r * s.cols + c))
fn transpose(s: Sheet) -> Sheet = Sheet { rows: s.cols, cols: s.rows, cells: t_cells(s, 0) }
fn t_cells(s: Sheet, c: Int) -> List[Int] = if c >= s.cols then [] else column(s, c) ++ t_cells(s, c + 1)
test transpose_2x4 = let m = transpose(Sheet { rows: 2, cols: 4, cells: [1, 2, 3, 4, 5, 6, 7, 8] }) in m.cells == [1, 5, 2, 6, 3, 7, 4, 8]
